39	    /**
40	     * Builds the owner's self link, formatted {@code '/api/owners/<id>'} where {@code id} is the
41	     * owner's id. Returns {@code null} when the owner has no id.
42	     */
43	    default String selfLink(Owner owner) {
44	        Integer id = owner.getId();
45	        if (id == null) {
46	            return null;
47	        }
48	        return "/api/owners/" + id;
49	    }
50	
51	    /**
52	     * Derives the owner's age band from the birth date, computed as the owner's age on the
53	     * registration date: {@code MINOR} when under 18, {@code ADULT} from 18 to 64, and
54	     * {@code SENIOR} at 65 or older. Returns {@code null} when the birth date or registration
