233	    /**
234	     * Reads the caller-supplied {@code Idempotency-Key} header from the current request, returning
235	     * {@code null} when the header is absent or blank so callers can treat those uniformly as "no key".
236	     *
237	     * @return the trimmed idempotency key, or {@code null} when none was supplied
238	     */
239	    private String idempotencyKey() {
240	        String value = request.getHeader(IDEMPOTENCY_KEY_HEADER);
241	        if (value == null || value.isBlank()) {
242	            return null;
243	        }
244	        return value.strip();
245	    }
