341	
342	    /**
343	     * Counts how many existing owners share the given first and last name, compared
344	     * case-insensitively, at the moment before the new owner is persisted. The result is
345	     * stored on the owner as its {@code namesakeCount}, so it reflects the population as it
346	     * stood when the owner was created rather than being recomputed on later reads.
347	     *
348	     * @param firstName the first name of the owner being created
349	     * @param lastName the last name of the owner being created
350	     * @return the number of pre-existing owners with the same first and last name
351	     */
352	    private int countNamesakes(String firstName, String lastName) {
353	        String first = firstName == null ? "" : firstName;
354	        String last = lastName == null ? "" : lastName;
355	        return (int) this.clinicService.findAllOwners().stream()
356	            .filter(existing -> first.equalsIgnoreCase(existing.getFirstName())
357	                && last.equalsIgnoreCase(existing.getLastName()))
358	            .count();
359	    }
360	
361	    /**
362	     * Builds the customer code for a newly created owner, formatted {@code '<REGION>-<HASH8>'} where
363	     * {@code REGION} is the region code derived from the owner's postcode (see {@link #deriveRegion})
364	     * and {@code HASH8} is the first 8 upper-case hex characters of the SHA-256 digest of the owner's
365	     * normalized telephone concatenated with the last name. For example an owner in the NSW postcode
366	     * range gets a code such as {@code 'NSW-3F2A1B9C'}.
367	     *
368	     * <p>When the computed code collides with an existing owner's customer code, it is de-duplicated
369	     * by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that makes the result
370	     * unique across all existing owners' customer codes. The de-duplicated code is what gets assigned.
371	     *
372	     * @param owner the owner being created, whose postcode, city and last name feed the code
373	     * @param normalizedTelephone the owner's E.164-normalized telephone
374	     * @return the assigned customer code, de-duplicated against existing owners if necessary
375	     */
376	    private String buildCustomerCode(Owner owner, String normalizedTelephone) {
377	        String region = deriveRegion(owner.getPostcode(), owner.getCity());
378	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
379	        String hash8 = sha256Hex8(normalizedTelephone + lastName);
380	        String baseCode = region + "-" + hash8;
381	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
382	            .map(Owner::getCustomerCode)
383	            .filter(code -> code != null)
384	            .collect(java.util.stream.Collectors.toSet());
385	        if (!existingCodes.contains(baseCode)) {
386	            return baseCode;
387	        }
388	        int n = 2;
389	        while (existingCodes.contains(baseCode + "-" + n)) {
390	            n++;
391	        }
392	        return baseCode + "-" + n;
393	    }
394	
395	    /**
396	     * Derives an owner's region code, preferring the postcode: the region whose {@link #REGION_POSTCODES}
397	     * range contains the (4-digit) postcode is returned, falling back to the fixed {@link #CITY_REGION}
398	     * city table when the postcode is absent or in no known range, and finally to {@code "UNKNOWN"}.
399	     *
400	     * @param postcode the owner's postcode, may be {@code null}
401	     * @param city the owner's city, used to resolve the region when the postcode does not
402	     * @return the canonical region string, or {@code "UNKNOWN"} when neither source resolves a region
403	     */
404	    private String deriveRegion(String postcode, String city) {
405	        if (postcode != null) {
406	            try {
407	                int value = Integer.parseInt(postcode.trim());
408	                for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
409	                    int[] range = entry.getValue();
410	                    if (value >= range[0] && value <= range[1]) {
411	                        return entry.getKey();
412	                    }
413	                }
414	            } catch (NumberFormatException ex) {
415	                // Not a numeric postcode; fall back to the city table below.
416	            }
417	        }
418	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
419	    }
420	
421	    /**
422	     * Computes the first 8 upper-case hex characters (the first 4 bytes) of the SHA-256 digest of the
423	     * given input's UTF-8 bytes.
424	     *
425	     * @param input the string to hash
426	     * @return the 8-character upper-case hex prefix of the SHA-256 digest
427	     */
428	    private String sha256Hex8(String input) {
429	        try {
430	            byte[] digest = MessageDigest.getInstance("SHA-256")
431	                .digest(input.getBytes(StandardCharsets.UTF_8));
432	            StringBuilder hex = new StringBuilder();
433	            for (int i = 0; i < 4; i++) {
434	                hex.append(String.format("%02X", digest[i]));
435	            }
436	            return hex.toString();
437	        } catch (NoSuchAlgorithmException ex) {
438	            throw new IllegalStateException("SHA-256 not available", ex);
439	        }
440	    }
441	
442	    /**
443	     * Rejects an owner payload that is missing or blank in any of the required fields
444	     * (firstName, lastName, address, city, telephone). The bean-validation constraints on
445	     * {@link OwnerFieldsDto} already reject {@code null} values and most malformed input, but
446	     * a present-yet-blank {@code address} or {@code city} would otherwise slip through, so this
447	     * guard enforces the rule uniformly for every required field.
448	     *
449	     * @param ownerFieldsDto the submitted owner payload
450	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
451	     */
452	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
453	        List<String> invalidFields = new ArrayList<>();
454	        if (isBlank(ownerFieldsDto.getFirstName())) {
455	            invalidFields.add("firstName");
456	        }
457	        if (isBlank(ownerFieldsDto.getLastName())) {
458	            invalidFields.add("lastName");
459	        }
460	        if (isBlank(ownerFieldsDto.getAddressLine1())
461	            && isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
462	            invalidFields.add("address");
463	        }
464	        if (isBlank(ownerFieldsDto.getCity())) {
465	            invalidFields.add("city");
466	        }
467	        if (isBlank(ownerFieldsDto.getTelephone())) {
468	            invalidFields.add("telephone");
469	        }
470	        if (!invalidFields.isEmpty()) {
471	            throw new InvalidOwnerFieldsException(invalidFields);
472	        }
473	    }
474	
475	    private boolean isBlank(String value) {
476	        return value == null || value.isBlank();
477	    }
478	
479	    /**
480	     * Whether an existing owner has been soft-deleted. A soft-deleted owner retains its row but is
481	     * excluded from the create endpoint's duplicate and identity checks, so it never blocks the
482	     * creation of a new owner. A {@code null} flag (an owner predating the soft-delete column) is
483	     * treated as not deleted.
484	     *
485	     * @param owner an existing owner
486	     * @return {@code true} if the owner is flagged deleted
487	     */
488	    private boolean isDeleted(Owner owner) {
489	        return Boolean.TRUE.equals(owner.getDeleted());
490	    }
491	
492	    /**
493	     * Validates a supplied owner postcode. The postcode is optional: a {@code null} value is
494	     * accepted and the request stays backward-compatible. When present it must be a 4-digit value,
495	     * and must fall within the inclusive range allowed for the owner's city region per the fixed
496	     * {@link #CITY_REGION} / {@link #REGION_POSTCODES} tables (NSW 2000-2099, VIC 3000-3099,
497	     * QLD 4000-4099). A city with no known region accepts any 4-digit postcode. The value is stored
498	     * and returned exactly as given.
499	     *
500	     * @param postcode the submitted postcode, may be {@code null} when absent
501	     * @param city the owner's city, used to resolve the region whose range the postcode must satisfy
502	     * @throws InvalidOwnerFieldsException if a present postcode is not 4 digits or is out of range
503	     */
504	    private void validatePostcode(String postcode, String city) {
505	        if (postcode == null) {
506	            return;
507	        }
508	        if (!postcode.matches("[0-9]{4}")) {
509	            throw new InvalidOwnerFieldsException(List.of("postcode"));
510	        }
511	        String region = city == null ? null : CITY_REGION.get(city);
512	        if (region == null) {
513	            return;
514	        }
515	        int[] range = REGION_POSTCODES.get(region);
516	        int value = Integer.parseInt(postcode);
517	        if (value < range[0] || value > range[1]) {
518	            throw new InvalidOwnerFieldsException(List.of("postcode"));
519	        }
520	    }
521	
522	    /**
523	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets are stripped.
524	     * A leading {@code '+'} and its country code are kept as-is; otherwise the country code {@code '+61'}
525	     * is assumed and a single leading {@code '0'} is dropped from the national digits. The result must be
526	     * a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} normalizes to
527	     * {@code "+61412345678"}. The E.164 string is what gets stored and returned.
528	     *
529	     * @param telephone the raw telephone value from the submitted owner payload
530	     * @return the normalized E.164 telephone number
531	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
532	     */
533	    private String normalizeTelephone(String telephone) {
534	        String raw = telephone == null ? "" : telephone.strip();
535	        boolean hasCountryCode = raw.startsWith("+");
536	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
537	        String digits;
538	        if (hasCountryCode) {
539	            digits = cleaned.substring(1);
540	        } else {
541	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
542	            digits = "61" + national;
543	        }
544	        if (!digits.matches("[0-9]{8,15}")) {
545	            throw new InvalidOwnerFieldsException(List.of("telephone"));
546	        }
547	        validateNationalNumberLength(digits);
548	        return "+" + digits;
549	    }
550	
551	    /**
552	     * Validates that the national-number portion of a normalized E.164 number (the digits after the
553	     * country calling code) has the exact length required for that country. The country code is matched
554	     * against {@link #NATIONAL_NUMBER_LENGTHS} (e.g. {@code +61} requires 9 national digits, {@code +1}
555	     * requires 10). Numbers whose country code is not listed are left to the generic length bounds.
556	     *
557	     * @param digits the normalized E.164 digits, without the leading {@code '+'}
558	     * @throws InvalidOwnerFieldsException if the national-number length is wrong for the country code
559	     */
560	    private void validateNationalNumberLength(String digits) {
561	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTHS.entrySet()) {
562	            String countryCode = entry.getKey();
563	            if (digits.startsWith(countryCode)) {
564	                int nationalLength = digits.length() - countryCode.length();
565	                if (nationalLength != entry.getValue()) {
566	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
567	                }
568	                return;
569	            }
570	        }
571	    }
572	
573	    /**
574	     * Best-effort conversion of an existing telephone value to E.164 form for duplicate comparison,
575	     * returning {@code null} when the value cannot form a valid E.164 number.
576	     *
577	     * @param telephone an existing owner's stored telephone value
578	     * @return the E.164 form, or {@code null} if it cannot be normalized
579	     */
580	    private String toE164OrNull(String telephone) {
581	        try {
582	            return normalizeTelephone(telephone);
583	        } catch (InvalidOwnerFieldsException ex) {
584	            return null;
585	        }
586	    }
587	
588	    /**
589	     * Normalizes an optional owner email. A {@code null} value is left untouched (the field is optional).
590	     * When a value is present it must be a syntactically valid address (see {@link #EMAIL_PATTERN}); the
591	     * accepted value is trimmed and lower-cased before it is stored and returned.
592	     *
593	     * @param email the raw email value from the submitted owner payload, may be {@code null}
594	     * @return {@code null} if no email was supplied, otherwise the lower-cased email
595	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address,
596	     *         or if its domain is on the disposable-domain blocklist ({@link #DISPOSABLE_EMAIL_DOMAINS})
597	     */
598	    private String normalizeEmail(String email) {
599	        if (email == null) {
600	            return null;
601	        }
602	        String trimmed = email.strip();
603	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
604	            throw new InvalidOwnerFieldsException(List.of("email"));
605	        }
606	        String normalized = trimmed.toLowerCase(Locale.ROOT);
607	        String domain = normalized.substring(normalized.indexOf('@') + 1);
608	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
609	            throw new InvalidOwnerFieldsException(List.of("email"));
610	        }
611	        return normalized;
612	    }
613	
614	    /**
615	     * Rejects creating an owner that would be a second member of an existing household. The household
616	     * is keyed on {@code (lastName, postcode)} through the deterministic {@link #householdId}, so any
617	     * existing owner carrying the same {@code householdId} makes the owner being created a household
618	     * duplicate. Such an owner is rejected with a 409, <em>unless</em> the request opts into
619	     * {@code sharesHousehold}: a declared household member deliberately bypasses this block and is
620	     * created as an additional member of the household.
621	     *
622	     * @param owner the owner being created, whose computed household id is matched
623	     * @param sharesHousehold whether the request declared the owner a shared-household member
624	     * @throws DuplicateOwnerIdentityException if another owner already belongs to the same household
625	     */
626	    private void rejectDuplicateIdentity(Owner owner, boolean sharesHousehold) {
627	        if (sharesHousehold) {
628	            return;
629	        }
630	        String householdId = owner.getHouseholdId();
631	        boolean duplicate = householdId != null && this.clinicService.findAllOwners().stream()
632	            .filter(existing -> !isDeleted(existing))
633	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
634	        if (duplicate) {
635	            throw new DuplicateOwnerIdentityException(householdId);
636	        }
637	    }
638	
639	    /**
640	     * Flags a soft ("possible") duplicate on the owner being created. Unlike a hard duplicate (which is
641	     * rejected outright by {@link #rejectDuplicateIdentity}), a soft duplicate is still created: it is an
642	     * owner that is not a hard duplicate but shares an existing owner's last name (compared
643	     * case-insensitively, see {@link #normalizeForComparison}) and postcode while carrying a <em>different</em>
644	     * telephone. When such an existing owner is found, {@code possibleDuplicate} is set {@code true} and
645	     * {@code possibleDuplicateOf} is set to that owner's id (the earliest by id when several match); otherwise
646	     * {@code possibleDuplicate} is {@code false} and {@code possibleDuplicateOf} stays {@code null}. Both values
647	     * are snapshotted on the owner so they reflect the population as it stood when the owner was created.
648	     *
649	     * <p>A declared household member (a request that set {@code sharesHousehold} to bypass the household
650	     * duplicate block) is never a <em>suspected</em> duplicate: it is knowingly created as another member
651	     * of the household, so {@code possibleDuplicate} is left {@code false} and {@code possibleDuplicateOf}
652	     * {@code null} without consulting the existing population.
653	     *
654	     * @param owner the owner being created, whose last name and postcode are matched
655	     * @param normalizedTelephone the E.164 telephone of the owner being created
656	     * @param sharesHousehold whether the request declared the owner a shared-household member
657	     */
658	    private void assignPossibleDuplicate(Owner owner, String normalizedTelephone, boolean sharesHousehold) {
659	        if (sharesHousehold) {
660	            owner.setPossibleDuplicateOf(null);
661	            owner.setPossibleDuplicate(false);
662	            return;
663	        }
664	        String postcode = owner.getPostcode();
665	        Integer matchId = null;
666	        if (postcode != null) {
667	            String lastName = normalizeForComparison(owner.getLastName());
668	            for (Owner existing : this.clinicService.findAllOwners()) {
669	                if (!isDeleted(existing)
670	                    && postcode.equals(existing.getPostcode())
671	                    && lastName.equals(normalizeForComparison(existing.getLastName()))
672	                    && !normalizedTelephone.equals(toE164OrNull(existing.getTelephone()))
673	                    && existing.getId() != null
674	                    && (matchId == null || existing.getId() < matchId)) {
675	                    matchId = existing.getId();
676	                }
677	            }
678	        }
679	        owner.setPossibleDuplicateOf(matchId);
680	        owner.setPossibleDuplicate(matchId != null);
681	    }
682	
683	    /**
684	     * The maximum number of owners a single city may contain. Once a city already holds this many
685	     * owners, creating another owner in that city is rejected.
686	     */
687	    private static final int MAX_OWNERS_PER_CITY = 50;
688	
689	    /**
690	     * Rejects creating an owner in a city that already contains {@link #MAX_OWNERS_PER_CITY} or more
691	     * owners. Existing owners' cities are compared case-insensitively with surrounding and repeated
692	     * internal whitespace collapsed (see {@link #normalizeForComparison}), matching the per-city
693	     * counting used elsewhere.
694	     *
695	     * @param city the city of the owner being created
696	     * @throws OwnerCityCapacityExceededException if the city already contains the maximum number of owners
697	     */
698	    /**
699	     * The maximum number of owners that may be registered on a single day. Once this many owners
700	     * already share a {@code registrationDate}, creating another owner for that day is rejected.
701	     */
702	    private static final int MAX_OWNERS_PER_DAY = 100;
703	
704	    /**
705	     * Fixed list of public holidays. A registration date that lands on one of these dates is not a
706	     * business day and is rolled forward to the next non-holiday weekday.
707	     */
708	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
709	        LocalDate.of(2026, 1, 1),
710	        LocalDate.of(2026, 1, 26),
711	        LocalDate.of(2026, 4, 25),
712	        LocalDate.of(2026, 12, 25),
713	        LocalDate.of(2026, 12, 28));
714	
715	    /**
716	     * Rejects creating an owner on a day that has already reached {@link #MAX_OWNERS_PER_DAY} or more
717	     * owner registrations. Existing owners are counted by their {@code registrationDate} matching the
718	     * registration date of the owner being created.
719	     *
720	     * @param registrationDate the registration date of the owner being created
721	     * @throws DailyOwnerLimitExceededException if the day has already reached the maximum number of owners
722	     */
723	    /**
724	     * Rolls an effective registration date forward onto a business day. A registration date must fall
725	     * on a weekday that is not a public holiday: when the supplied or defaulted date is a Saturday, a
726	     * Sunday, or a listed public holiday it is rolled forward one day at a time until it reaches the
727	     * next non-holiday business day, and that adjusted date becomes the owner's {@code registrationDate}.
728	     * A date that is already a non-holiday weekday is returned unchanged. Every value derived from the
729	     * registration date (the daily create-limit count, the membership number's year segment, and so on)
730	     * uses this adjusted date.
731	     *
732	     * @param date the effective registration date (supplied in the request or defaulted to the server date)
733	     * @return the same date if it is a non-holiday weekday, otherwise the next non-holiday business day
734	     */
735	    /**
736	     * Rejects creating an owner whose supplied {@code registrationDate} is later than the server's
737	     * current date. A registration date is not permitted to lie in the future; a {@code null} date
738	     * (defaulted to the server date) and any date on or before today are accepted. The check runs
739	     * against the date exactly as supplied, before it is rolled forward onto a business day.
740	     *
741	     * @param registrationDate the registration date supplied in the request, may be {@code null}
742	     * @throws FutureRegistrationDateException if the supplied date is after the server date
743	     */
744	    private void rejectFutureRegistrationDate(LocalDate registrationDate) {
745	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
746	            throw new FutureRegistrationDateException(registrationDate);
747	        }
748	    }
749	
750	    private LocalDate rollToBusinessDay(LocalDate date) {
751	        LocalDate adjusted = date;
752	        while (!isBusinessDay(adjusted)) {
753	            adjusted = adjusted.plusDays(1);
754	        }
755	        return adjusted;
756	    }
757	
758	    private boolean isBusinessDay(LocalDate date) {
759	        DayOfWeek day = date.getDayOfWeek();
760	        if (day == DayOfWeek.SATURDAY || day == DayOfWeek.SUNDAY) {
761	            return false;
762	        }
763	        return !PUBLIC_HOLIDAYS.contains(date);
764	    }
765	
766	    private void rejectDailyLimitReached(LocalDate registrationDate) {
767	        long ownersToday = this.clinicService.findAllOwners().stream()
768	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
769	            .count();
770	        if (ownersToday >= MAX_OWNERS_PER_DAY) {
771	            throw new DailyOwnerLimitExceededException(registrationDate);
772	        }
773	    }
774	
775	    /**
776	     * The number of owners that must already share a {@code registrationDate} before a newly created
777	     * owner for that day is flagged with a bulk-signup warning. Once more than this many owners have
778	     * been created for the day, the new owner's {@code bulkSignupWarning} is {@code true}.
779	     */
780	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
781	
782	    /**
783	     * Determines whether the owner being created should carry a bulk-signup warning. The warning is
784	     * raised when more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created for
785	     * the same registration date at the time this owner is created. Existing owners are counted by their
786	     * {@code registrationDate} matching the registration date of the owner being created, mirroring the
787	     * daily create-limit accumulation.
788	     *
789	     * @param registrationDate the registration date of the owner being created
790	     * @return {@code true} if the day already holds more than the threshold number of owners
791	     */
792	    private boolean isBulkSignupDay(LocalDate registrationDate) {
793	        long ownersToday = this.clinicService.findAllOwners().stream()
794	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
795	            .count();
796	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
797	    }
798	
799	    private void rejectCityAtCapacity(String city) {
800	        String normalizedCity = normalizeForComparison(city);
801	        long ownersInCity = this.clinicService.findAllOwners().stream()
802	            .filter(existing -> normalizedCity.equals(normalizeForComparison(existing.getCity())))
803	            .count();
804	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
805	            throw new OwnerCityCapacityExceededException(city);
806	        }
807	    }
808	
809	    /**
810	     * Counts how many owners belong to the household the owner being created has just been assigned to,
811	     * inclusive of that owner. Existing owners are matched by their {@code householdId} equalling the
812	     * given identifier; the owner being created is added on because it is counted before being persisted.
813	     * An owner that did not opt into a shared household (its {@code householdId} is {@code null}) is a
814	     * household of one. The value is snapshotted on the owner.
815	     *
816	     * @param householdId the household identifier assigned to the owner being created, may be {@code null}
817	     * @return the number of household members, including the owner being created
818	     */
819	    private int countHousehold(String householdId) {
820	        if (householdId == null) {
821	            return 1;
822	        }
823	        long existing = this.clinicService.findAllOwners().stream()
824	            .filter(owner -> householdId.equals(owner.getHouseholdId()))
825	            .count();
826	        return (int) existing + 1;
827	    }
828	
829	    /**
830	     * Derives the deterministic household identifier for a given last name and postcode: the first 12
831	     * hex characters of the SHA-256 digest of {@code '<normalizedLastName>|<postcode>'}, where the last
832	     * name is normalized for case- and whitespace-insensitive comparison (see
833	     * {@link #normalizeForComparison}) and a {@code null} postcode contributes an empty segment. Every
834	     * owner that shares a last name and postcode therefore resolves to the exact same identifier,
835	     * regardless of creation order, making them members of one household.
836	     *
837	     * @param lastName the owner's last name
838	     * @param postcode the owner's postcode, may be {@code null}
839	     * @return the deterministic household identifier
840	     */
841	    private String householdId(String lastName, String postcode) {
842	        String key = normalizeForComparison(lastName) + "|" + (postcode == null ? "" : postcode);
843	        try {
844	            byte[] digest = MessageDigest.getInstance("SHA-256")
845	                .digest(key.getBytes(StandardCharsets.UTF_8));
846	            StringBuilder hex = new StringBuilder();
847	            for (int i = 0; i < 6; i++) {
848	                hex.append(String.format("%02x", digest[i]));
849	            }
850	            return hex.toString();
851	        } catch (NoSuchAlgorithmException ex) {
852	            throw new IllegalStateException("SHA-256 not available", ex);
853	        }
854	    }
855	
856	    /**
857	     * Normalizes a value for case-insensitive, whitespace-insensitive comparison: leading and trailing
858	     * whitespace is stripped, every run of internal whitespace is collapsed to a single space, and the
859	     * result is lower-cased. A {@code null} value normalizes to the empty string.
860	     *
861	     * @param value the value to normalize, may be {@code null}
862	     * @return the normalized value
863	     */
864	    private String normalizeForComparison(String value) {
865	        if (value == null) {
866	            return "";
867	        }
868	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
869	    }
870	
871	    /**
872	     * Normalizes an owner address for storage and comparison: leading and trailing whitespace is
873	     * stripped, every run of internal whitespace is collapsed to a single space, the value is
874	     * upper-cased, and common street-type abbreviations are expanded ({@code ST -> STREET},
875	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). For example {@code "  12  main  st "} normalizes to
876	     * {@code "12 MAIN STREET"}. A {@code null} value normalizes to the empty string. This is the form
877	     * that is stored, returned, and used for every address comparison (household duplicate detection
878	     * and the shared household id).
879	     *
880	     * @param address the raw address value from the submitted owner payload, may be {@code null}
881	     * @return the normalized address
882	     */
883	    /**
884	     * Applies address normalization to the owner and derives the composed {@code address}, preferring
885	     * the structured fields over the flat {@code address} input for backward compatibility. When a
886	     * non-blank {@code addressLine1} is supplied, both structured lines are normalized (see
887	     * {@link #normalizeAddress}) and stored, and the composed {@code address} becomes the normalized
888	     * {@code addressLine1}, with a single space and the normalized {@code addressLine2} appended when an
889	     * {@code addressLine2} was supplied. Otherwise the flat {@code address} is normalized and stored, and
890	     * the structured lines are cleared. The stored {@code address} is the form every later step reads.
891	     *
892	     * @param owner the owner being created, whose raw address fields are normalized in place
893	     */
894	    private void applyAddress(Owner owner) {
895	        String line1 = owner.getAddressLine1();
896	        if (line1 != null && !line1.isBlank()) {
897	            String normalizedLine1 = normalizeAddress(line1);
898	            String normalizedLine2 = normalizeAddress(owner.getAddressLine2());
899	            owner.setAddressLine1(normalizedLine1);
900	            if (!normalizedLine2.isEmpty()) {
901	                owner.setAddressLine2(normalizedLine2);
902	                owner.setAddress(normalizedLine1 + " " + normalizedLine2);
903	            } else {
904	                owner.setAddressLine2(null);
905	                owner.setAddress(normalizedLine1);
906	            }
907	        } else {
908	            owner.setAddressLine1(null);
909	            owner.setAddressLine2(null);
910	            owner.setAddress(normalizeAddress(owner.getAddress()));
911	        }
912	    }
913	
914	    private String normalizeAddress(String address) {
915	        if (address == null) {
916	            return "";
917	        }
918	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
919	        if (collapsed.isEmpty()) {
920	            return "";
921	        }
922	        String[] tokens = collapsed.split(" ");
923	        StringBuilder normalized = new StringBuilder();
924	        for (int i = 0; i < tokens.length; i++) {
925	            if (i > 0) {
926	                normalized.append(' ');
927	            }
928	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
929	        }
930	        return normalized.toString();
931	    }
932	}
