                                      address_line1 TEXT,
                                      address_line2 TEXT,
                                      title      TEXT,
                                      city       TEXT,
                                      telephone  TEXT,
                                      email      TEXT,
                                      postcode   VARCHAR(4),
                                      registration_date DATE,
                                      birth_date DATE,
                                      customer_code TEXT,
                                      household_id TEXT,
                                      namesake_count INT,
                                      bulk_signup_warning BOOLEAN,
